 display:block;max-width:265px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--musical-dim);font-size:11px
}
.huw-musical--workspace .huw-musical-app-actions{display:flex;align-items:center;justify-content:flex-end;gap:6px;min-width:0}
.huw-musical--workspace .huw-musical-app-actions button,
.huw-musical--workspace .huw-musical-view-mode{
 padding:6px 8px;height:29px;border:1px solid #485e73;border-radius:6px;
 background:#25354b;color:#e9f3fa;font:inherit;white-space:nowrap;cursor:pointer
}
.huw-musical--workspace .huw-musical-app-actions button[aria-pressed="true"]{background:#28637d;border-color:#63b6d8}
.huw-musical--workspace .huw-musical-links{
 display:flex;align-items:center;flex-wrap:nowrap;gap:6px;margin:0;padding:0;
 max-width:min(28vw,350px);overflow:hidden
}
.huw-musical--workspace .huw-musical-links a{
 display:inline-flex;align-items:center;height:29px;min-width:0;white-space:nowrap;
 text-decoration:none;padding:5px 7px;border-radius:6px;
 border:1px solid #485e73;background:#25354b;color:#c6e8f8;font:inherit
}
.huw-musical--workspace .huw-musical-links a:hover{background:#2a546f}
.huw-musical--workspace .huw-musical-layout{
 flex:0 0 var(--musical-preview-height);height:var(--musical-preview-height);
 min-height:0;max-height:none;display:grid;
 grid-template-columns:minmax(0,1fr) minmax(0,1fr);
 overflow:hidden;border-bottom:0;background:#0f1723
}
.huw-musical--workspace[data-preview-mode="stage"] .huw-musical-layout{grid-template-columns:1fr}
