.huw-musical--workspace .huw-musical-subtitle{
 margin:0 0 5px;font-size:11px;letter-spacing:.04em;font-weight:700;flex:0 0 auto
}
.huw-musical--workspace .huw-musical-canvas{
 flex:1 1 auto;display:flex;align-items:center;justify-content:center;
